guide.Add("GenericAll|users",new string[]{"Broad control of a user object may expose password-reset or credential-related changes, subject to protections and the actual effective rights.","Identify whether this is a person or service account and verify the relevant reset, credential and ownership rights.","Replace unnecessary user-object full control with narrowly scoped support or service-management permissions.","Rescan the user ACL and alternative group grants, then test the legitimate support or service workflow.","Avoid resetting a password merely to remove an ACL grant; credential changes can interrupt services and affect access to protected data."});
guide.Add("GenericWrite|users",new string[]{"Property-write access on a user can affect attributes such as service names or key credentials. It is not itself a password-reset permission.","Check which attributes are writable, the required authentication infrastructure and protections on this account.","Delegate only the user attributes required by the service-management role instead of broad property writes.","Rescan the attribute permissions and confirm that approved service names and enrollment workflows still work.","Removing required service-name or enrollment delegation can interrupt authentication or device enrollment."});
