        private static Dictionary<string,string[]> CreateGuide()
        {
            var guide=new Dictionary<string,string[]>(StringComparer.OrdinalIgnoreCase);
            guide.Add("ADCSESC1",new string[]{"Certificate enrollment identity candidate","The same principal has modeled enrollment capabilities on an eligible template and its publishing CA.","Imported evidence supports subject-supplied authentication certificates without approval or applicable signatures, plus direct-root/NTAuth trust and an enabled same-domain CA host.","Enrollment may permit an identity-bearing authentication certificate, subject to effective access and current server enforcement.","Review the exact template, publishing CA, separate enrollment grant witnesses, root and NTAuth objects, and host. Confirm the approved identity and enrollment workflow before changing permissions.","Supported scope is imported direct-root CAs only. This is not verified certificate issuance, exploitation or a guarantee of current authentication behavior.","Review the exact template, publishing CA, separate enrollment grant witnesses, root and NTAuth objects, and host. Confirm the approved identity and enrollment workflow before changing permissions."});
guide.Add("GPOAppliesTo",new string[]{"Computer policy scope candidate","Collected directory evidence places this computer in the enabled GPO link scope, with supported Read and Apply grants.","The model checked link enforcement, blocked inheritance, a unique DN-consistent containment chain, known security-enabled group memberships and the GPO computer-policy flags.","Control of the GPO may affect this computer if policy content can also be changed and the client processes it. This is a review candidate.","Review the recorded link root, containment chain, Read/Apply membership witnesses and GPO ACL. Separately verify SYSVOL write access, client processing, extensions and actual resultant policy. Remove unnecessary GPO edit or link permissions only through normal change control.","This is not an observed policy execution or confirmed administrative access. WMI-filtered GPOs, relevant denies, unsupported ACLs, missing metadata and conflicting snapshots suppress this inference. User, site and loopback policy are not derived.","Review the recorded link root, containment chain, Read/Apply membership witnesses and GPO ACL. Separately verify SYSVOL write access, client processing, extensions and actual resultant policy. Remove unnecessary GPO edit or link permissions only through normal change control."});
guide.Add("ReplicationAnalysisBlocked",new string[]{"Replication inference requires review","A native domain ACL contains a replication-related deny or an unsupported applicable ACE.","The collector recorded a conservative stop marker for membership-based DCSync inference.","The automatic permission intersection is skipped for this domain.","Review the original domain ACL and full effective token before assessing replication capability.","This marker does not prove that replication is denied for every principal. Existing direct grants remain separate observations.","Review the original domain ACL and full effective token before assessing replication capability."});
guide.Add("HasIssuancePolicy",new string[]{"Certificate-policy association","The directory records a template policy OID or an issuance-policy group link.","The relevant policy OID or group-link attribute was collected.","The association supplies context for certificate-policy review.","Review template publication, policy OIDs, linked groups and authentication prerequisites together.","This association alone grants no group membership and is not traversed as a privilege path.","Review template publication, policy OIDs, linked groups and authentication prerequisites together."});
guide.Add("OIDGroupLink",new string[]{"Certificate-policy association","The directory records a template policy OID or an issuance-policy group link.","The relevant policy OID or group-link attribute was collected.","The association supplies context for certificate-policy review.","Review template publication, policy OIDs, linked groups and authentication prerequisites together.","This association alone grants no group membership and is not traversed as a privilege path.","Review template publication, policy OIDs, linked groups and authentication prerequisites together."});
guide.Add("HostsSiteServer",new string[]{"Directory site association","The directory links a server or subnet to its site inventory.","A server-reference, parent-site or subnet-site attribute was collected.","Site information helps explain directory topology and administrative scope.","Verify the referenced computer, site and subnet configuration with the directory owner.","This is topology inventory, not an observed login, endpoint connection or privilege grant.","Verify the referenced computer, site and subnet configuration with the directory owner."});
guide.Add("SiteServerOf",new string[]{"Directory site association","The directory links a server or subnet to its site inventory.","A server-reference, parent-site or subnet-site attribute was collected.","Site information helps explain directory topology and administrative scope.","Verify the referenced computer, site and subnet configuration with the directory owner.","This is topology inventory, not an observed login, endpoint connection or privilege grant.","Verify the referenced computer, site and subnet configuration with the directory owner."});
guide.Add("InSite",new string[]{"Directory site association","The directory links a server or subnet to its site inventory.","A server-reference, parent-site or subnet-site attribute was collected.","Site information helps explain directory topology and administrative scope.","Verify the referenced computer, site and subnet configuration with the directory owner.","This is topology inventory, not an observed login, endpoint connection or privilege grant.","Verify the referenced computer, site and subnet configuration with the directory owner."});
guide.Add("GenericAll",new string[]{"Full control","The source has broad control over the target directory object.","The dataset contains a GenericAll permission from the source to this target.","Control of an account, group, computer or policy can extend access to other resources. The effect depends on the target type.","Confirm the business owner and intended delegation. Review the target ACL, including inheritance, and remove unnecessary full-control grants.","A collected allow right approximates effective access; group tokens, deny entries and object protections still need checking.","Replace unnecessary full-control delegation with the specific permissions the role requires."});
guide.Add("GenericWrite",new string[]{"Write object properties","The source can change a broad set of properties on the target object.","A GenericWrite grant was recorded on the target.","Changing security-sensitive properties may create additional access, depending on the target.","Inspect the target type and delegated attributes. Replace broad write access with the specific permissions the role needs.","This does not mean the source can change every protected attribute or immediately take over the target.","Remove unnecessary broad property-write rights and delegate only the required attributes."});
guide.Add("WriteDacl",new string[]{"Change permissions","The source can change the permission list on the target.","A WriteDacl grant was recorded.","Someone controlling the source could grant additional access to the target.","Inspect who can edit this ACL and why. Remove unnecessary permission-management rights and check inheritance.","Confirm effective rights and protected-object behavior before deciding the grant is exploitable.","Remove unnecessary ACL-edit rights. If the grant is inherited, review its originating container."});
guide.Add("OwnsRaw",new string[]{"Raw or limited ownership evidence","The dataset records ownership or an ownership-related permission.","Raw evidence is kept separately from derived control paths.","This inventory row alone does not establish DACL-edit access.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots.","Raw and limited observations are not automatically traversed as full object control.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots."});
guide.Add("WriteOwnerRaw",new string[]{"Raw or limited ownership evidence","The dataset records ownership or an ownership-related permission.","Raw evidence is kept separately from derived control paths.","This inventory row alone does not establish DACL-edit access.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots.","Raw and limited observations are not automatically traversed as full object control.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots."});
guide.Add("OwnsLimitedRights",new string[]{"Raw or limited ownership evidence","The dataset records ownership or an ownership-related permission.","Raw evidence is kept separately from derived control paths.","This inventory row alone does not establish DACL-edit access.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots.","Raw and limited observations are not automatically traversed as full object control.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots."});
guide.Add("WriteOwnerLimitedRights",new string[]{"Raw or limited ownership evidence","The dataset records ownership or an ownership-related permission.","Raw evidence is kept separately from derived control paths.","This inventory row alone does not establish DACL-edit access.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots.","Raw and limited observations are not automatically traversed as full object control.","Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots."});
guide.Add("ForceChangePassword",new string[]{"Reset another account’s password","The source has a password-reset right over the target account.","A ForceChangePassword grant was recorded.","An unnecessary reset delegation can allow someone to take control of another account.","Confirm the helpdesk or service delegation and its scope. Limit reset rights to the required accounts.","This is a permission observation, not evidence that any password was changed.","Limit password-reset delegation to the intended support role and account scope."});
guide.Add("DCSync",new string[]{"Directory replication rights","The dataset records a DCSync capability candidate on this domain.","Paired direct grants were collected, or both prerequisite grants were inferred through recorded group memberships.","Unnecessary replication permissions can expose domain credential material.","Confirm this is a domain controller or an approved replication service. Review both domain-root replication grants, membership witnesses and deny rules.","A direct allow or inferred relationship does not establish full-token effective access or successful credential replication.","Retain replication permissions only for domain controllers and explicitly approved replication services."});
guide.Add("AllExtendedRights",new string[]{"Broad extended rights","The source has broad extended rights on the target.","An AllExtendedRights grant was recorded.","The available actions depend on the target, and can include sensitive account or domain operations.","Inspect the target’s extended rights and the business reason for the delegation. Prefer narrowly scoped rights.","Do not infer a particular attack from this label without checking the target and prerequisites. Grants on groups and other non-account objects are inventory only and do not imply group-membership control.","Replace broad extended-right grants with only the approved individual rights."});
guide.Add("AdminTo",new string[]{"Local administrator access","The source is represented as an administrator of the target computer.","Native local-group collection or an imported dataset recorded an administrator relationship.","Control of the source may give administrative control of that computer and access to sensitive data.","Check the computer’s local Administrators group, nested memberships, device tier and intended support role.","Actual remote access also depends on policies, token filtering, credentials and network reachability.","Remove unnecessary local-administrator membership, including nested assignments through policy."});
guide.Add("CanRDP",new string[]{"Remote desktop membership","The source has a recorded relationship associated with Remote Desktop access to the target.","Endpoint group enumeration or an imported dataset recorded CanRDP.","Remote interactive access may expose applications and data on the computer.","Review Remote Desktop Users, logon allow/deny policies, MFA and network restrictions.","Group membership alone does not prove that a remote desktop logon will succeed.","Remove unnecessary Remote Desktop membership and review logon allow/deny policy."});
guide.Add("HasSession",new string[]{"A user was observed logged on","The target user was reported as logged on to the source computer at collection time.","Endpoint enumeration or the imported data contained a session observation.","A privileged user on a lower-trust computer may increase exposure if that computer is compromised.","Confirm the session is current, check administrative logon practices, and separate privileged accounts from routine workstation use.","This can become stale quickly. It does not prove credentials are recoverable or that the user is still connected.","Move privileged administration to trusted administration hosts and end unneeded privileged sessions after coordinating with their owner."});
guide.Add("AllowedToAct",new string[]{"Resource-based delegation","The target computer’s delegation descriptor names the source as allowed to act on behalf of users.","The collector read the target’s resource-based delegation security descriptor.","Control of an allowed source account can permit impersonation to the target under suitable conditions.","Confirm the service dependency and approved delegating accounts. Review the target’s delegation descriptor.","User protections, protocol behavior and credentials affect the result; the relationship alone is not a successful impersonation.","Remove unauthorized principals from the target’s resource-based delegation descriptor."});
guide.Add("AllowedToDelegate",new string[]{"Constrained delegation","The source account has an allowed service target that resolves to this collected object.","An allowed-to-delegate SPN was resolved against the dataset’s service names.","Control of a delegation account may allow impersonation to the named service under suitable conditions.","Review the exact allowed services, protocol-transition setting, account ownership and protected-user policy.","An SPN-to-object link identifies a potential target. It does not prove every service on the computer is reachable or delegation will succeed.","Remove obsolete allowed-service targets and restrict delegation to approved service accounts and services."});
guide.Add("HasSIDHistory",new string[]{"Historical identity on an account","The source account contains the target SID in its SID history.","The collector read the account’s sIDHistory attribute.","Historical SIDs can retain access from an older identity or migration.","Confirm the migration purpose, expected history and remaining permissions. Remove obsolete history through an approved change.","Trust filtering and token behavior affect whether a historical SID grants access.","Remove obsolete SID history through the approved migration cleanup process after checking dependent access."});
guide.Add("AddAllowedToAct",new string[]{"Change a computer’s delegation permissions","The source has a recorded write permission on the target computer’s resource-based delegation descriptor.","A write-property ACE for msDS-AllowedToActOnBehalfOfOtherIdentity was recorded.","An unauthorized change could permit another identity to delegate to this computer when the required authentication conditions hold.","Review the provisioning role, exact ACE, deny rules and target protections. Remove unnecessary writes to this attribute.","This is permission to change the descriptor, not evidence that delegation is configured or that an identity can currently delegate.","Restrict writes that can change resource-based delegation on this computer."});
guide.Add("WriteAccountRestrictions",new string[]{"Change account restrictions","The source has a recorded write-property permission on the target account’s Account Restrictions property set.","A write-property ACE for property-set GUID 4c164200-20c0-11d0-a768-00aa006e0529 was recorded.","Changing writable account-restriction properties can affect account security when the required directory checks permit it.","Review the property-set members in this forest, deny rules, target protections and intended provisioning role. Delegate only the required individual properties where practical.","This does not establish that every property or account-control bit is writable, that delegation is configured, or that an account can be taken over. Full-token effective access still needs validation.","Delegate only the account-restriction properties required by the provisioning role."});
guide.Add("AddKeyCredentialLink",new string[]{"Change key credentials","The source can change key-credential data associated with the target.","The dataset includes an AddKeyCredentialLink relationship.","An unauthorized credential change could create another way to authenticate as the target.","Review who can write key credentials, legitimate enrollment requirements, and recent credential changes.","Authentication infrastructure and target-specific prerequisites still apply.","Restrict writes to key-credential data and review existing credentials against approved enrollment."});
guide.Add("WriteSPN",new string[]{"Change service names","The source can change service principal names on the target account.","A WriteSPN relationship was recorded.","Service-name changes can affect authentication and create credential-exposure opportunities.","Confirm who manages this service account and which SPNs it requires. Restrict unauthorized SPN changes.","Target properties and authentication prerequisites determine the practical risk.","Restrict service-name changes to the approved service-account management role."});
guide.Add("WriteGPLink",new string[]{"Change policy links","The source can change Group Policy links on the target.","A WriteGPLink relationship was recorded.","Changing policy links may change which settings apply to users or computers in scope.","Review policy-link delegation, linked policies, enforcement, filtering and affected objects.","Link-edit rights do not by themselves grant control of a policy or guarantee its application.","Restrict policy-link editing and review the linked policies and affected scope."});
guide.Add("SQLAdmin",new string[]{"Database administration","The dataset represents administrative rights on a SQL Server target.","An imported or collected SQLAdmin relationship was present.","Administrative database access may expose data and sensitive service configuration.","Validate the SQL role, business owner, service identity and least-privilege configuration.","The relationship does not prove operating-system administration or successful connection.","Reduce unnecessary SQL administrative privileges and review the database service identity."});
guide.Add("MemberOf",new string[]{"Group membership","The source is a member of the target group.","Direct or primary group membership was recorded.","The source may receive permissions assigned to this group. Membership is normal directory behavior.","Check whether membership is intended and whether the group grants sensitive access.","Nested groups and token behavior affect effective access. This is context, not a vulnerability by itself.","If this membership is unnecessary, remove the source from the target group after checking dependent access."});
guide.Add("Contains",new string[]{"Directory location","The source container contains the target object.","The directory object’s parent was recorded.","Location helps explain policy and inherited permissions.","Review the organizational structure and inheritance when investigating another permission.","Containment alone does not grant control.","Review the organizational structure and inheritance when investigating another permission."});
guide.Add("GPLink",new string[]{"Group Policy link configuration","A policy-link configuration references the target site, domain or organizational unit.","A Group Policy link was recorded; inspect its enabled/enforced metadata.","An enabled link may affect objects in scope; a disabled link is inventory only.","Review security filtering, inheritance, enforcement and policy settings.","A link alone does not prove application. Missing metadata is not evidence that a link is enabled.","Review security filtering, inheritance, enforcement and policy settings."});
guide.Add("PublishedTo",new string[]{"Template publication","The certificate template is published on the target certificate authority.","The authority’s certificateTemplates list referenced this template.","Publication helps establish where a template can be requested.","Review the template alongside the authority’s issuance and enrollment controls.","Publication alone does not establish an unsafe certificate configuration.","Review the template alongside the authority’s issuance and enrollment controls."});
guide.Add("TrustRelationship",new string[]{"Domain trust inventory","The collected domain has a recorded trust relationship with the remote domain.","A trustedDomain object was found in the directory.","Trust configuration affects cross-domain authentication boundaries.","Review direction, attributes, SID filtering, selective authentication and the business purpose.","This inventory link does not describe attack direction or prove cross-domain escalation.","Review direction, attributes, SID filtering, selective authentication and the business purpose."});
guide.Add("WriteOwner",new string[]{"Change an object owner","The source has a recorded permission to change the owner of the target directory object.","The ACL or imported record contains WriteOwner; the ownership model checks supported OWNER RIGHTS and captured policy context.","A new owner may obtain additional permission-management capability when the applicable server policy and descriptor permit it.","Inspect the projected assessment, target class, owner restrictions, relevant denies and captured policy before reviewing the unnecessary owner-change grant.","Changing an owner does not unconditionally grant every permission. Computer/MSA/gMSA restrictions and unsupported server behavior can suppress or qualify the projection.","Restrict who can change the owner and restore the intended ownership through an approved change."});
guide.Add("Owns",new string[]{"Recorded ownership capability","The source is the recorded owner of the target object, with modeled owner rights assessed separately.","Ownership was captured in the descriptor or imported record; raw observations and projected control are kept distinct.","An owner can sometimes manage the object DACL, subject to OWNER RIGHTS, relevant denies and supported server-policy exceptions.","Confirm the intended owner and inspect the assessment and original descriptor. Correct unauthorized ownership and unnecessary owner-related delegation through normal change control.","The owner is not necessarily an administrator of a computer endpoint. A raw owner observation, conditional legacy edge or suppressed projection is not verified effective access.","Confirm the intended owner, review owner-rights entries, and correct unauthorized ownership."});
guide.Add("GetChanges",new string[]{"Replicate directory changes","The source has one recorded domain replication prerequisite for directory changes.","The domain ACL or imported source reports the GetChanges extended right.","Combined with GetChangesAll on the same domain and an intersecting principal/token, this may support a modeled DCSync candidate.","Inspect both separate grants, their trustees, membership witnesses, domain identity and relevant deny context.","GetChanges alone is not modeled as DCSync and does not establish access to password-related replication data.","Inspect both separate grants, their trustees, membership witnesses, domain identity and relevant deny context."});
guide.Add("GetChangesAll",new string[]{"Replicate sensitive directory changes","The source has the recorded GetChangesAll replication prerequisite on a domain.","The domain ACL or imported source reports this extended right.","The model combines this with GetChanges on the same domain when both reach the same principal through supported memberships.","Review the paired prerequisite and membership witnesses; distinguish an explicit source grant from a derived intersection.","A single prerequisite, unknown token context or incomplete domain ACL does not establish a usable DCSync operation.","Review the paired prerequisite and membership witnesses; distinguish an explicit source grant from a derived intersection."});
guide.Add("AddMember",new string[]{"Manage group membership","The source has a modeled capability to change the membership of the target group.","An applicable membership write or imported AddMember observation was recorded.","Adding another principal to a security group can give that principal the permissions and memberships carried by the group.","Check the exact member-attribute grant, inherited source, security-enabled group state, token restrictions and intended provisioning delegation.","This is not proof that membership was changed. Distribution groups, protected targets, denies and directory checks can affect the practical result.","Limit group-membership management to approved administrators or a narrowly scoped provisioning role."});
guide.Add("AddSelf",new string[]{"Add self to a group","The source has a recorded self-membership capability on the target group.","The ACL or imported record identifies the self-membership right rather than general membership management.","The source may be able to place its own identity into a security group and obtain group-derived capabilities.","Verify the self-membership right, actual trustee and target group; narrow only the unnecessary delegation.","AddSelf is narrower than adding arbitrary accounts. Effective token, target protections and directory checks remain prerequisites.","Remove unnecessary self-membership rights from this group."});
guide.Add("CanPSRemote",new string[]{"Potential PowerShell remoting access","The source has a recorded remote-management authorization or relevant group assignment on the target computer.","Endpoint or supported imported collection recorded the assignment.","The principal may be able to use a permitted remoting endpoint if the service, network, authentication and endpoint configuration allow it.","Check the exact WinRM/PowerShell endpoint authorization, local and policy assignments, service availability and intended management role.","Remote-management membership alone does not prove local administrator access, access to every remoting endpoint or successful execution.","Remove unnecessary remote-management membership and review endpoint authorization."});
guide.Add("ExecuteDCOM",new string[]{"Potential DCOM access","The source has a recorded DCOM-related authorization or group assignment on the target computer.","Endpoint or imported collection recorded a relevant DCOM membership or permission.","Some applications may permit remote activation or execution when application-specific launch, access and authentication conditions hold.","Review application-specific DCOM launch/access permissions, the relevant service, network reachability and the approved support role.","A DCOM group assignment is not a guarantee that a particular application can be activated or that execution is privileged.","Remove unnecessary DCOM group membership and review application-specific launch permissions."});
guide.Add("ReadLAPSPassword",new string[]{"Potential LAPS password read","The source has a recorded capability related to reading a managed local administrator password for this computer.","Supported directory ACL or imported evidence reports the password-read capability.","An authorized reader may obtain access to the managed local account, subject to the deployment and authentication controls.","Identify legacy versus Windows LAPS, the managed account, exact readable attribute, encryption/decryptor authorization and current rotation policy.","No password value was collected by this viewer. Modern encrypted LAPS can require additional decryption rights; a read-related observation alone does not prove usable administrator access.","Restrict local administrator password readers and review the managed account’s scope and rotation."});
guide.Add("ReadGMSAPassword",new string[]{"Potential gMSA managed-password read","The source is recorded as a permitted reader in the supported managed-service account password-reader model.","Native collection evaluates the embedded msDS-GroupMSAMembership descriptor or the importer supplies a supported observation.","A principal able to retrieve the managed secret may act as the gMSA where that service identity is authorized.","Review the gMSA reader descriptor, security-group memberships, intended service hosts and the account downstream rights.","This is a modeled permission, not a collected secret. A normal account ACL alone is not sufficient native evidence, and full-token conditions still require validation.","Restrict managed-service password readers to approved service hosts and administrators."});
guide.Add("DumpSMSAPassword",new string[]{"Potential standalone MSA secret access","The source host or principal has a recorded relationship to obtaining a standalone managed service account secret.","Supported imported collection reports the MSA-specific capability.","Access to an assigned managed service identity can affect the services and resources authorized to that account.","Confirm the managed account class, assigned host, source identity, actual collection provenance and intended service deployment.","Standalone MSA and gMSA reader mechanisms differ. The relationship does not mean Tessera retrieved a password or that every host can obtain the secret.","Review access to this managed service account and restrict the hosts and principals that can obtain its secret."});
guide.Add("Enroll",new string[]{"Certificate enrollment observation","The source has a recorded enrollment-related allow observation on a certificate template or CA object.","Directory or imported ACL data contains an Enroll classification.","The observation can be a prerequisite for certificate issuance when the template, publication and actual CA-service rights also qualify.","Identify the target class and evidence source. For ESC1, inspect both the template and the same publishing CA service grant.","Directory-object Enroll is inventory and cannot substitute for successful CA-service permission collection. Enrollment alone is not a domain takeover or an issued certificate.","Identify the target class and evidence source. For ESC1, inspect both the template and the same publishing CA service grant."});
guide.Add("AutoEnroll",new string[]{"Certificate auto-enrollment observation","The source has a recorded auto-enrollment-related permission on a certificate template.","The template ACL or imported record contains AutoEnroll.","The permission can participate in an approved automatic certificate enrollment workflow when policy, enrollment rights and issuance prerequisites permit it.","Review template Enroll and AutoEnroll permissions, policy applicability, publication, CA-service authorization and actual enrollment behavior.","AutoEnroll is not a substitute for the required enrollment permissions, and its presence alone is not an ESC1 or privilege-path derivation.","Review template Enroll and AutoEnroll permissions, policy applicability, publication, CA-service authorization and actual enrollment behavior."});
guide.Add("ManageCA",new string[]{"Unverified CA-management observation","A ManageCA-related observation is associated with the CA directory object or supplied source.","Native collection can classify related directory masks; imported summaries must be checked for their actual permission authority.","Actual CA-service management authority can affect CA configuration, but directory and service permissions can differ.","Review the original evidence authority and actual CA-service descriptor before deciding whether the principal can change CA configuration.","The observation is inventory and excluded from automatic management-control paths. It is not proof of CA-service administration or certificate issuance.","Review the original evidence authority and actual CA-service descriptor before deciding whether the principal can change CA configuration."});
guide.Add("ManageCertificates",new string[]{"Unverified certificate-management observation","A certificate-management-related observation is associated with the CA object or supplied source.","Native directory masks or supported import data produced the classification.","Actual certificate-manager authority may affect request disposition and certificate-management workflows when the service grants it.","Verify the real CA-service permission, role separation, request restrictions and approved certificate-management responsibilities.","Directory-object masks do not prove the service role. Tessera does not infer certificate approval, issuance or a GoldenCert path from this inventory label.","Verify the real CA-service permission, role separation, request restrictions and approved certificate-management responsibilities."});
            return guide;
        }
        [STAThread]
        public static void Run(string indexPath)
        {
            Application.EnableVisualStyles();
            using(var window=new DesktopWindow(indexPath))window.ShowDialog();
        }
        internal static Dictionary<string,object> Map(object value){return (Dictionary<string,object>)value;}
        internal static string Text(Dictionary<string,object> row,string key){object value;return row.TryGetValue(key,out value)?Convert.ToString(value,CultureInfo.InvariantCulture):"";}
        internal static long Number(Dictionary<string,object> row,string key){return Convert.ToInt64(row[key],CultureInfo.InvariantCulture);}
        internal static bool Flag(Dictionary<string,object> row,string key){return row.ContainsKey(key)&&Convert.ToBoolean(row[key],CultureInfo.InvariantCulture);}
        internal static List<object> Rows(Dictionary<string,object> row){return (List<object>)row["Rows"];}
        internal static string ChangeProcess="Before changing it: Confirm the business owner and dependent services. Save the exact current ACL, membership or delegation, including inheritance.\r\n\r\nValidation: Rescan the same scope with comparable permissions and endpoint coverage. Check this chain and alternative paths, and test legitimate service/support workflows.\r\n\r\nRollback: Restore only the documented original setting through the approved change process if required access breaks. Reassess narrower delegation.";
        internal static string Explain(Dictionary<string,object> edge)
        {
            string type=Text(edge,"ty");string[] h;
            if(!Guide.TryGetValue(type,out h))h=new string[]{type,"A recorded relationship in the supplied index.","The dataset contains this relationship.","Its effect depends on the object types and source data.","Verify the relationship's source documentation and prerequisites.","Do not assume that an unfamiliar relationship establishes effective access.","Inspect the original evidence before choosing a change."};
            string[] context;string targetKind=Text(edge,"tt");if(targetKind.Length==0)targetKind=Text(edge,"tk");
            ContextGuide.TryGetValue(type+"|"+targetKind,out context);
            string derived="",evidence=Text(edge,"Evidence");
            if(evidence.Length>0 && JsonRecordReader.ExtractField(evidence,"Derivation")=="DCSyncMembershipIntersectionV1")
            {
                var a=new List<string>(JsonRecordReader.StringArray(evidence,"GetChangesMembership"));
                var b=new List<string>(JsonRecordReader.StringArray(evidence,"GetChangesAllMembership"));
                derived="\r\n\r\nHow this relationship was derived\r\nBoth replication permissions reach this principal on the same domain through recorded security-group memberships. Effective access has not been verified.\r\nGetChanges membership witness: "+string.Join(" → ",a.ToArray())+"\r\nGetChangesAll membership witness: "+string.Join(" → ",b.ToArray());
                if(JsonRecordReader.ExtractField(evidence,"WitnessLimited")=="true")derived+="\r\nWitness preview limited to 64 objects; inspect the full membership graph.";
            }
            string contextual=context==null?"":"\r\n\r\nPrerequisites to verify\r\n"+context[1]+"\r\n\r\nChange impact\r\n"+context[4];
            if(type=="GPLink"&&evidence.Length>0&&JsonRecordReader.ExtractField(evidence,"GpoLinkMetadataVersion")=="1")
                derived="\r\n\r\nRecorded link options\r\nEnabled: "+JsonRecordReader.ExtractField(evidence,"Enabled")+"; enforced: "+JsonRecordReader.ExtractField(evidence,"Enforced")+"; options: "+JsonRecordReader.ExtractField(evidence,"LinkOptions")+". Link configuration does not prove policy application."+(JsonRecordReader.ExtractField(evidence,"GpoLinkEvidenceConflict")!=null?" Conflicting snapshots suppress automatic scope inference.":"");
            if(evidence.Length>0&&JsonRecordReader.ExtractField(evidence,"Derivation")=="GpoComputerScopeV1")
            {
                derived="\r\n\r\nHow this scope was derived\r\nLink root: "+JsonRecordReader.ExtractField(evidence,"LinkRoot")+"; enforced: "+JsonRecordReader.ExtractField(evidence,"Enforced");
                foreach(string key in new[]{"ContainmentChain","ReadMembership","ApplyMembership"})derived+="\r\n"+key+": "+string.Join(" → ",new List<string>(JsonRecordReader.StringArray(evidence,key)).ToArray());
                derived+="\r\nComputer-policy scope candidate only. SYSVOL, policy contents, client processing and resultant policy were not verified. Everyone/Authenticated Users are implicit token identities; other token witnesses use recorded security-enabled memberships.";
            }
            if(evidence.Length>0&&JsonRecordReader.ExtractField(evidence,"Derivation")=="AdcsEsc1DirectRootV1")
            {
                derived="\r\n\r\nHow this relationship was derived\r\n"+JsonRecordReader.ExtractField(evidence,"EvidenceNote");if(JsonRecordReader.ExtractField(evidence,"PostExportGroupClassification")=="true")derived+="\r\nConditional mixed-time candidate: group classification was read after export; original permissions and memberships were not revalidated.";
                foreach(string field in new[]{"Template","EnterpriseCA","RootCA","NTAuthStore","HostingComputer","CertThumbprint","TemplateGrant","CAServiceGrant"})derived+="\r\n"+field+": "+JsonRecordReader.ExtractField(evidence,field);
                foreach(string field in new[]{"TemplateMembership","CAServiceMembership"})derived+="\r\n"+field+": "+string.Join(" → ",new List<string>(JsonRecordReader.StringArray(evidence,field)).ToArray());
            }
            string ownershipDerivation=evidence.Length==0?null:JsonRecordReader.ExtractField(evidence,"Derivation");
            if(ownershipDerivation=="OwnershipControlV1"||ownershipDerivation=="OwnershipLegacyV1")
            {
                string assessment=JsonRecordReader.ExtractField(evidence,"Assessment"),reason=JsonRecordReader.ExtractField(evidence,"Reason");
                derived="\r\n\r\nOwnership assessment\r\n"+assessment+": "+reason+"\r\nPolicy: "+(JsonRecordReader.ExtractField(evidence,"OwnerPolicyMode")??"not captured")+"; "+(JsonRecordReader.ExtractField(evidence,"PolicySource")??"legacy collection")+". Effective access and server enforcement were not verified.";
                if(assessment=="Suppressed projection")
                {h=(string[])h.Clone();context=null;contextual="";h[0]="Ownership observation: projection suppressed";h[1]="Raw ownership evidence is retained, but this row does not establish control.";h[2]=reason;h[3]="This observation is excluded from control-path traversal. Suppression is not proof that every possible permission is denied.";h[6]="Validate the evidence and intended delegation before considering changes.";}
            }
            return h[0]+"\r\n"+Text(edge,"sn")+" → "+Text(edge,"tn")+"\r\n"+type+derived+"\r\n\r\nWhat this means\r\n"+(context==null?h[1]:context[0])+"\r\n\r\nWhy it is shown\r\n"+h[2]+"\r\n\r\nPossible impact\r\n"+h[3]+contextual+"\r\n\r\nWhat to verify\r\n"+h[4]+"\r\n\r\nLimits\r\n"+h[5]+"\r\n\r\nRecommended change to review\r\n"+(context==null?h[6]:context[2])+(context==null?"":"\r\n\r\nHow to verify this change\r\n"+context[3])+"\r\n\r\n"+ChangeProcess+"\r\n\r\nReference\r\nBloodHound relationship documentation: https://bloodhound.specterops.io/resources/edges\r\nTessera support and derivation limits: PATH-PARITY.md, OWNERSHIP.md, GPO-SCOPE.md and ADCS-SCOPE.md.";
        }
    }

